class EventEmitter:
    def __init__(self):
        self._handlers = {}
    def on(self, event, fn):
        self._handlers.setdefault(event, set()).add(fn)
    def off(self, event, fn):
        self._handlers.get(event, set()).discard(fn)
    def emit(self, event, *args):
        for fn in list(self._handlers.get(event, ())):
            fn(*args)
