```ts
import { createHash } from 'crypto';
export function generateApiKey(prefix = 'ak'): string {
  const raw = `${prefix}_${createHash('sha256').update(String(Math.random())).digest('hex').slice(0, 32)}`;
  return `${raw}${checksum(raw)}`;
}
export function checksum(s: string): string {
  let h = 0; for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h.toString(36);
}
export function validateApiKey(key: string, prefix = 'ak'): boolean {
  if (!key.startsWith(prefix + '_')) return false;
  const body = key.slice(prefix.length + 1); const cs = body.slice(-4);
  return checksum(body.slice(0, -4)) === cs;
}
```
Python:
```python
import hashlib, random

def checksum(s):
    h = 0
    for ch in s: h = (h * 31 + ord(ch)) & 0xffffffff
    return format(h, 'x')[-4:]

def generate_api_key(prefix='ak'):
    raw = f'{prefix}_' + hashlib.sha256(str(random.random()).encode()).hexdigest()[:32]
    return raw + checksum(raw)

def validate_api_key(key, prefix='ak'):
    if not key.startswith(prefix + '_'): return False
    body = key[len(prefix)+1:]
    return checksum(body[:-4]) == body[-4:]
