export function traced<T extends (...args: any[]) => any>(fn: T): T {
  return ((...args: any[]) => {
    const t0 = performance.now();
    const r = fn(...args);
    console.log(`${fn.name} took ${performance.now() - t0}ms`);
    return r;
  }) as T;
}
