import ("encoding/json"; "os"; "time")
func WatchConfig(path string, onChange func(map[string]any)) {
    stat, _ := os.Stat(path); last := stat.ModTime()
    for {
        stat, _ = os.Stat(path)
        if stat.ModTime() != last {
            last = stat.ModTime()
            var cfg map[string]any
            data, _ := os.ReadFile(path)
            json.Unmarshal(data, &cfg)
            onChange(cfg)
        }
        time.Sleep(time.Second)
    }
}
```

